package com.streamcraft.core.runtime;
import com.streamcraft.core.model.DataEntity; import com.streamcraft.shared.file.HdfsFileSourceConfig; import org.apache.flink.api.connector.source.*; import org.apache.flink.core.io.SimpleVersionedSerializer;
final class HdfsFileSource implements Source<DataEntity,HdfsFileSourceSplit,HdfsFileEnumeratorState>{private static final long serialVersionUID=1L;private final HdfsFileSourceConfig config;HdfsFileSource(HdfsFileSourceConfig c){config=c;}public Boundedness getBoundedness(){return config.readMode()==HdfsFileSourceConfig.ReadMode.FULL?Boundedness.BOUNDED:Boundedness.CONTINUOUS_UNBOUNDED;}public SourceReader<DataEntity,HdfsFileSourceSplit> createReader(SourceReaderContext c){return new HdfsFileSourceReader(c,config);}public SplitEnumerator<HdfsFileSourceSplit,HdfsFileEnumeratorState> createEnumerator(SplitEnumeratorContext<HdfsFileSourceSplit> c)throws Exception{return new HdfsFileEnumerator(c,config,new HdfsFileEnumeratorState(java.util.List.of(),java.util.Set.of()));}public SplitEnumerator<HdfsFileSourceSplit,HdfsFileEnumeratorState> restoreEnumerator(SplitEnumeratorContext<HdfsFileSourceSplit> c,HdfsFileEnumeratorState s)throws Exception{return new HdfsFileEnumerator(c,config,s);}public SimpleVersionedSerializer<HdfsFileSourceSplit> getSplitSerializer(){return new HdfsFileSourceSplitSerializer();}public SimpleVersionedSerializer<HdfsFileEnumeratorState> getEnumeratorCheckpointSerializer(){return new HdfsFileEnumeratorStateSerializer();}}
